function html(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(body);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    chunks.push(chunk);
    size += chunk.length;
    if (size > 65536) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && url.pathname === '/') {
      html(response, 200, projectsPage('', projectFilter(url.searchParams.get('filter')), searchQuery(url.searchParams)));
    } else if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const filter = projectFilter(form.get('filter'));
      const name = (form.get('name') || '').trim();
      if (!name) {
        html(response, 400, projectsPage('Project name is required', filter, searchQuery(form)));
        return;
      }
      createProject.run(name);
      response.writeHead(303, { Location: projectsLocation(filter, searchQuery(form)) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/[1-9]\d*\/(archive|restore)$/.test(url.pathname)) {
      const [, , projectId, action] = url.pathname.split('/');
      const form = await readForm(request);
      const result = setProjectArchived.run(action === 'archive' ? 1 : 0, projectId);
      if (!result.changes) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      response.writeHead(303, { Location: projectsLocation(projectFilter(form.get('filter') || (action === 'archive' ? 'Active' : 'Archived')), searchQuery(form)) });
      response.end();
    } else if (request.method === 'GET' && /^\/projects\/[1-9]\d*$/.test(url.pathname)) {
      const project = getProject.get(url.pathname.split('/')[2]);
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1><form action="/"><button>Projects</button></form>'));
        return;
      }
      html(response, 200, projectPage(project, taskFilter(url.searchParams.get('filter')), '', priorityFilter(url.searchParams.get('priorityFilter')), appliedRange(url.searchParams), undefined, searchQuery(url.searchParams)));
    } else if (request.method === 'POST' && /^\/projects\/[1-9]\d*\/due-range$/.test(url.pathname)) {
      const project = getProject.get(url.pathname.split('/')[2]);
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const priority = priorityFilter(form.get('priorityFilter'));
      const range = { from: (form.get('from') || '').trim(), through: (form.get('through') || '').trim() };
      const error = rangeError(range);
      if (error) {
        html(response, 400, projectPage(project, filter, error, priority, appliedRange(form), range, searchQuery(form)));
        return;
      }
      response.writeHead(303, { Location: projectLocation(project.id, filter, priority, range, searchQuery(form)) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/[1-9]\d*\/default-priority$/.test(url.pathname)) {
      const project = getProject.get(url.pathname.split('/')[2]);
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const priority = priorityFilter(form.get('priorityFilter'));
      if (project.archived) {
        html(response, 403, projectPage(project, filter, 'Archived projects cannot be changed', priority, appliedRange(form), undefined, searchQuery(form)));
        return;
      }
      const defaultPriority = form.get('priority');
      if (!priorities.includes(defaultPriority)) {
        html(response, 400, projectPage(project, filter, 'Invalid task priority', priority, appliedRange(form), undefined, searchQuery(form)));
        return;
      }
      setDefaultPriority.run(defaultPriority, project.id);
      response.writeHead(303, { Location: projectLocation(project.id, filter, priority, appliedRange(form), searchQuery(form)) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/[1-9]\d*\/rename$/.test(url.pathname)) {
      const project = getProject.get(url.pathname.split('/')[2]);
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const priority = priorityFilter(form.get('priorityFilter'));
      if (project.archived) {
        html(response, 403, projectPage(project, filter, 'Archived projects cannot be changed', priority, appliedRange(form), undefined, searchQuery(form)));
        return;
      }
      const name = (form.get('name') || '').trim();
      if (!name) {
        html(response, 400, projectPage(project, filter, 'Project name is required', priority, appliedRange(form), undefined, searchQuery(form)));
        return;
      }
      renameProject.run(name, project.id);
      response.writeHead(303, { Location: projectLocation(project.id, filter, priority, appliedRange(form), searchQuery(form)) });
      response.end();
    } else if (request.method === 'POST' && /^\/projects\/[1-9]\d*\/tasks(?:\/[1-9]\d*(?:\/(?:rename|priority|due-date|move|notes))?)?$/.test(url.pathname)) {
      const [, , projectId, , taskId, action] = url.pathname.split('/');
      const project = getProject.get(projectId);
      if (!project) {
        html(response, 404, page('Not found', '<h1>Project not found</h1>'));
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      const prioritySelection = priorityFilter(form.get('priorityFilter'));
      if (project.archived) {
        html(response, 403, projectPage(project, filter, 'Archived projects cannot be changed', prioritySelection, appliedRange(form), undefined, searchQuery(form)));
        return;
      }
      if (taskId) {
        let result;
        if (action === 'move') {
          const destinationId = form.get('destination');
          const destination = /^[1-9]\d*$/.test(destinationId || '') ? getProject.get(destinationId) : null;
          if (!destination || destination.archived || destination.id === project.id) {
            html(response, 400, projectPage(project, filter, 'Choose an active destination project', prioritySelection, appliedRange(form), undefined, searchQuery(form)));
            return;
          }
          result = moveTask(destination.id, taskId, projectId);
        } else if (action === 'rename') {
          const title = (form.get('title') || '').trim();
          if (!title) {
            html(response, 400, projectPage(project, filter, 'Task title is required', prioritySelection, appliedRange(form), undefined, searchQuery(form)));
            return;
          }
          result = renameTask.run(title, taskId, projectId);
        } else if (action === 'notes') {
          result = setTaskNotes.run(form.get('notes') || '', taskId, projectId);
        } else if (action === 'due-date') {
          const dueDate = (form.get('dueDate') || '').trim();
          if (!validDueDate(dueDate)) {
            html(response, 400, projectPage(project, filter, 'Due date must be a valid YYYY-MM-DD date', prioritySelection, appliedRange(form), undefined, searchQuery(form)));
            return;
          }
          result = setTaskDueDate.run(dueDate, taskId, projectId);
        } else if (action === 'priority') {
          const priority = form.get('priority');
          if (!priorities.includes(priority)) {
            html(response, 400, projectPage(project, filter, 'Invalid task priority', prioritySelection, appliedRange(form), undefined, searchQuery(form)));
            return;
          }
          result = setTaskPriority.run(priority, taskId, projectId);
        } else {
          result = updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, projectId);
        }
        if (!result.changes) {
          html(response, 404, page('Not found', '<h1>Task not found</h1>'));
          return;
        }
      } else {
        const title = (form.get('title') || '').trim();
        if (!title) {
          html(response, 400, projectPage(project, filter, 'Task title is required', prioritySelection, appliedRange(form), undefined, searchQuery(form)));
          return;
        }
        createTask(projectId, title, project.default_priority);
      }
      response.writeHead(303, { Location: projectLocation(projectId, filter, prioritySelection, appliedRange(form), searchQuery(form)) });
      response.end();
    } else {
      html(response, 404, page('Not found', '<h1>Page not found</h1>'));
    }
  } catch (error) {
    console.error(error);
    html(response, error.status || 500, page('Error', '<h1>Unable to complete request</h1>'));
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => {
      db.close();
      process.exit(0);
    });
  });
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';
import { DatabaseSync } from 'node:sqlite';

test('notes migrate, remain plain text, preserve filters and travel with tasks', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-notes-'));
  const database = join(directory, 'data.sqlite');
  // A pre-notes database with existing task data and remembered positions.
  const legacy = new DatabaseSync(database);
  legacy.exec(`
    CREATE TABLE projects (id INTEGER PRIMARY KEY, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0, default_priority TEXT NOT NULL DEFAULT 'Normal');
    CREATE TABLE tasks (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, priority TEXT NOT NULL DEFAULT 'Normal', due_date TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL);
    CREATE TABLE task_positions (task_id INTEGER NOT NULL, project_id INTEGER NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(task_id, project_id), UNIQUE(project_id, position));
    INSERT INTO projects VALUES (1, 'Source', 0, 'Normal'), (2, 'Destination', 0, 'Low');
    INSERT INTO tasks VALUES (1, 1, 'First', 1, 'High', '2024-02-29', 1), (2, 1, 'Second', 0, 'Normal', '', 2);
    INSERT INTO task_positions VALUES (1, 1, 1), (2, 1, 2);
  `);
  const before = legacy.prepare('SELECT * FROM tasks ORDER BY id').all().map(task => ({ ...task }));
  legacy.close();
  let child;
  let base;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: database },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    base = await new Promise((resolve, reject) => {
      let output = '';
      child.stdout.on('data', chunk => {
        output += chunk;
        const match = output.match(/listening on port (\d+)/);
        if (match) resolve(`http://127.0.0.1:${match[1]}`);
      });
      child.on('error', reject);
      child.on('exit', code => reject(new Error(`Server exited: ${code}`)));
    });
  }
  async function stop() {
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
    child = null;
  }
  const get = async path => (await fetch(base + path)).text();
  const post = (path, values = {}) => fetch(base + path, {
    method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
  });
  const stored = () => {
    const db = new DatabaseSync(database);
    try { return db.prepare('SELECT * FROM tasks ORDER BY id').all(); }
    finally { db.close(); }
  };
  const titles = body => [...body.matchAll(/aria-label="Complete ([^"]+)"/g)].map(match => match[1]);
  const notes = '\n  leading spaces\nUnicode: 雪 🦊\n</textarea><script>alert("x")</script> & literal\n  ';
  const state = { filter: 'Completed', priorityFilter: 'High', dueFrom: '2024-02-29', dueThrough: '2024-02-29', search: 'first' };
  const location = '/projects/1?filter=Completed&priorityFilter=High&dueFrom=2024-02-29&dueThrough=2024-02-29&search=first';
  try {
    await start();
    assert.deepEqual(stored().map(({ notes, ...task }) => task), before);
    assert.deepEqual(stored().map(task => task.notes), ['', '']);
    assert.match(await get('/projects/1'), /name="notes" rows="4">\n<\/textarea>/);
    const saved = await post('/projects/1/tasks/1/notes', { ...state, notes });
    assert.equal(saved.status, 303);
    assert.equal(saved.headers.get('location'), location);
    assert.equal(stored()[0].notes, notes);
    assert.deepEqual(stored().map(({ notes, ...task }) => task), before);
    let body = await get(location);
    assert.deepEqual(titles(body), ['First']);
    assert.match(body, /name="notes" rows="4">\n\n  leading spaces/);
    assert.match(body, /&lt;\/textarea&gt;&lt;script&gt;alert\(&quot;x&quot;\)&lt;\/script&gt; &amp; literal/);
    assert.equal(body.includes('<script>'), false);
    assert.deepEqual(titles(await get('/projects/1?search=Unicode')), []);
    await post('/projects/1/tasks', { title: 'Third' });
    assert.equal(stored()[2].notes, '');
    await post('/projects/1/tasks/1/rename', { title: 'First renamed' });
    await post('/projects/1/rename', { name: 'Renamed source' });
    await post('/projects/1/tasks/1/move', { ...state, destination: '2' });
    assert.deepEqual(titles(await get(location)), []);
    assert.equal(stored()[0].notes, notes);
    await post('/projects/2/tasks/1/move', { destination: '1' });
    assert.deepEqual(titles(await get('/projects/1')), ['First renamed', 'Second', 'Third']);
    assert.equal(stored()[0].priority, 'High');
    await post('/projects/1/archive');
    body = await get(location);
    assert.match(body, /name="notes" rows="4" disabled>/);
    assert.match(body, /disabled>Save notes<\/button>/);
    assert.equal((await post('/projects/1/tasks/1/notes', { notes: 'blocked' })).status, 403);
    assert.equal((await post('/projects/2/tasks/1/notes', { notes: 'wrong owner' })).status, 404);
    await stop();
    await start();
    assert.equal(stored()[0].notes, notes);
    await post('/projects/1/restore');
    body = await get(location);
    assert.match(body, /name="notes" rows="4">/);
    assert.match(body, /<button type="submit">Save notes<\/button>/);
    await post('/projects/1/tasks/2/notes', { notes: '  \n\t  ' });
    assert.equal(stored()[1].notes, '  \n\t  ');
    await post('/projects/1/tasks/1/notes', { ...state, notes: '' });
    assert.equal(stored()[0].notes, '');
    assert.deepEqual(titles(await get(location)), ['First renamed']);
    await stop();
    await start();
    assert.equal(stored()[0].notes, '');
    assert.equal(stored()[1].notes, '  \n\t  ');
  } finally {
    if (child) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

